from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m strings by their LCS length with s, modulo 998244353."""
    mod = 998244353
    masks = {}
    for i, char in enumerate(s):
        masks[char] = masks.get(char, 0) | (1 << i)
    match_masks = list(masks.values())
    size = 1 << n
    transitions = []
    for state in range(size):
        destinations = []
        for mask in match_masks:
            x = state | mask
            destinations.append(x & ~(x - ((state << 1) | 1)))
        transitions.append(destinations)
    absent = 26 - len(match_masks)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following = [value * absent % mod for value in dp]
        for state, value in enumerate(dp):
            if value:
                for dest in transitions[state]:
                    following[dest] = (following[dest] + value) % mod
        dp = following
    answer = [0] * (n + 1)
    for state, value in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + value) % mod
    return answer

