    for mask in matches.values():
        row = []
        for state in range(size):
            x = state | mask
            row.append(x & ~(x - ((state << 1) | 1)))
        transitions.append(row)
    absent = 26 - len(matches)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [value * absent for value in dp]
        for state, value in enumerate(dp):
            if value:
                for row in transitions:
                    nxt[row[state]] += value
        dp = [value % mod for value in nxt]
