from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    even, odd = {}, {}
    for x in nums:
        nxt_even, nxt_odd = even.copy(), odd.copy()
        for product, bits in even.items():
            p = min(overflow, product * x)
            nxt_odd[p] = nxt_odd.get(p, 0) | (bits << x)
        for product, bits in odd.items():
            p = min(overflow, product * x)
            nxt_even[p] = nxt_even.get(p, 0) | (bits >> x)
        p = min(overflow, x)
        nxt_odd[p] = nxt_odd.get(p, 0) | (1 << (offset + x))
        even, odd = nxt_even, nxt_odd
    target = 1 << (offset + k)
    return max((p for p in even.keys() | odd.keys()
                if p <= limit and (even.get(p, 0) | odd.get(p, 0)) & target),
               default=-1)

