from functools import lru_cache


@lru_cache(maxsize=None)
def _count_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count unrestricted suffixes; sum zero denotes an unstarted number."""
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum == 0)
    if product == 0:
        # A real zero digit makes every completion beautiful.
        return 10 ** remaining
    total = 0
    for digit in range(10):
        next_product = product * digit if digit_sum or digit else 1
        total += _count_suffix(remaining - 1, digit_sum + digit, next_product)
    return total


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    total = 0
    digit_sum = 0
    product = 1
    for position, limit in enumerate(digits):
        remaining = len(digits) - position - 1
        for digit in range(limit):
            next_product = product * digit if digit_sum or digit else 1
            total += _count_suffix(remaining, digit_sum + digit, next_product)
        product = product * limit if digit_sum or limit else 1
        digit_sum += limit
    return total + int(digit_sum > 0 and product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when its digit product is divisible by its digit
    sum. Bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

