from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles exactly covers the grid.

    Each available tile may be used at most once. Tiles must align with grid
    cells, must not overlap, and cannot extend outside the h by w grid.
    """
    shapes = sorted(
        (tuple(sorted((a, b))) for a, b in tiles[:n]
         if (a <= h and b <= w) or (b <= h and a <= w)),
        key=lambda shape: shape[0] * shape[1],
        reverse=True,
    )
    count = len(shapes)
    cells = h * w
    full = (1 << cells) - 1

    # attainable[mask] has bit s set exactly when some subset of mask has area s.
    attainable = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        a, b = shapes[bit.bit_length() - 1]
        previous = attainable[mask ^ bit]
        attainable[mask] = previous | (previous << (a * b))

    placements = [[] for _ in range(cells)]
    for pos in range(cells):
        row, col = divmod(pos, w)
        for i, (a, b) in enumerate(shapes):
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    row_bits = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= row_bits << (pos + offset * w)
                    placements[pos].append((i, rectangle))

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = cells - occupied.bit_count()
        if not (attainable[remaining] >> needed) & 1:
            return False

        # A tile covering the first empty cell must start at that cell:
        # every earlier cell is already occupied.
        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1
        tried = set()
        for i, rectangle in placements[pos]:
            bit = 1 << i
            if not remaining & bit or rectangle & occupied:
                continue
            key = (shapes[i], rectangle)
            if key in tried:
                continue
            tried.add(key)
            if search(occupied | rectangle, remaining ^ bit):
                return True
        return False

    return search(0, (1 << count) - 1)

