def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions, and replacements can turn s
    into t using at most k operations.

    Supports strings of length up to 500000 and budgets up to 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    # For each diagonal d = x - y, keep the largest source position x
    # reachable with the current edit budget, after matching equal characters.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        return True
    previous = {0: x}

    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1

            # Replace the next character.
            old = previous.get(diagonal)
            if old is not None and old < n and old - diagonal < m:
                best = old + 1

            # Delete the next source character.
            old = previous.get(diagonal - 1)
            if old is not None and old < n:
                best = max(best, old + 1)

            # Insert the next target character.
            old = previous.get(diagonal + 1)
            if old is not None and old - (diagonal + 1) < m:
                best = max(best, old)

            if best < 0:
                continue
            x = best
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            current[diagonal] = x
        previous = current
    return False

