from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count x in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10**9 + 7.

    Args:
        num1: Lower bound, with 1 <= num1 <= 10**22.
        num2: Upper bound, with num1 <= num2 <= 10**22.
        min_sum: Minimum allowed digit sum, between 1 and 400.
        max_sum: Maximum allowed digit sum, between min_sum and 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > max_sum or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                dp(position + 1, total + digit, tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

