from collections import deque
from functools import lru_cache
from typing import List


@lru_cache(maxsize=1)
def _knight_graph():
    """Legal knight destinations for each square of the 50 by 50 board."""
    steps = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))
    graph = [[] for _ in range(2500)]
    for x in range(50):
        for y in range(50):
            for dx, dy in steps:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50:
                    graph[x * 50 + y].append(nx * 50 + ny)
    return graph


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    Return the total moves under optimal alternating pawn captures.

    The knight stays on a 50x50 board and each capture follows a shortest
    knight path. Alice maximizes total moves and Bob minimizes them, with
    Alice moving first. Other pawns do not block or force captures along
    the path. There are at most 15 pawns.
    """
    n = len(positions)
    squares = [x * 50 + y for x, y in positions] + [kx * 50 + ky]
    graph = _knight_graph()
    distances = []
    for start in squares:
        distance = [-1] * 2500
        distance[start] = 0
        queue = deque([start])
        while queue:
            square = queue.popleft()
            next_distance = distance[square] + 1
            for neighbor in graph[square]:
                if distance[neighbor] == -1:
                    distance[neighbor] = next_distance
                    queue.append(neighbor)
        distances.append([distance[target] for target in squares[:n]])

    @lru_cache(maxsize=None)
    def play(current: int, remaining: int) -> int:
        if not remaining:
            return 0
        alice_turn = (n - remaining.bit_count()) % 2 == 0
        best = -1 if alice_turn else 10 ** 9
        candidates = remaining
        while candidates:
            bit = candidates & -candidates
            pawn = bit.bit_length() - 1
            value = distances[current][pawn] + play(pawn, remaining ^ bit)
            if alice_turn:
                if value > best:
                    best = value
            elif value < best:
                best = value
            candidates ^= bit
        return best

    return play(n, (1 << n) - 1)

