from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Find the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    Vertices are numbered 1 through n. Return -1 if no such subtree exists.
    Runs in O(n) time and space for n up to 200,000.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    # A traversal order avoids recursion on deep input trees.
    parent = [0] * (n + 1)
    order = [1]
    for u in order:
        for v in adjacency[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # down[u] includes u and assumes that the edge to its parent is selected.
    # Thus u either contributes a leaf, or selects exactly three child edges.
    down = [1] * (n + 1)
    answer = -1
    for u in reversed(order):
        best = []
        for v in adjacency[u]:
            if parent[v] == u:
                value = down[v]
                # Retain only the four largest child contributions.
                i = 0
                while i < len(best) and best[i] >= value:
                    i += 1
                if i < 4:
                    best.insert(i, value)
                    if len(best) > 4:
                        best.pop()

        if len(best) >= 3:
            down[u] = 1 + best[0] + best[1] + best[2]
            if parent[u]:
                # Complete this branch with its parent as a leaf.
                answer = max(answer, down[u] + 1)
        if len(best) == 4:
            # u is the highest internal vertex and has no parent edge.
            answer = max(answer, 1 + sum(best))

    return answer

