from functools import lru_cache


@lru_cache(maxsize=None)
def _completions(remaining: int, digit_sum: int, product: int) -> int:
    """Count valid suffixes; sum zero means no significant digit yet."""
    if product == 0:
        # A significant zero makes every continuation beautiful.
        return 10 ** remaining
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum == 0)

    result = _completions(
        remaining - 1, digit_sum, 1 if digit_sum == 0 else 0
    )
    for digit in range(1, 10):
        result += _completions(
            remaining - 1, digit_sum + digit, product * digit
        )
    return result


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    result = 0
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(limit):
            next_product = product * digit if digit_sum or digit else 1
            result += _completions(remaining, digit_sum + digit, next_product)
        product = product * limit if digit_sum or limit else 1
        digit_sum += limit
    return result + int(product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)
